import{_ as n,a0 as s,w as o,s as d,ao as a,I as t,x as l,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const A=JSON.parse('{"title":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量 | LCTT x X-CMD","titleTemplate":false,"description":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量 | LCTT (RHCSA Series) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量 | LCTT (RHCSA Series) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables","title":"RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量","tag":"RHCSA Series","desc":""},"relativePath":"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables.md","filePath":"[post].md"}'),w={name:"RHCSA Series/RHCSA Series--Part 11--Firewall Essentials and Network Traffic Control Using FirewallD and Iptables.md"};function f(m,e,u,b,T,C){const p=s("Link");return o(),d("div",null,[e[32]||(e[32]=a(`<h1 id="rhcsa-系列-十一-使用-firewalld-和-iptables-来控制网络流量" tabindex="-1">RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量 <a class="header-anchor" href="#rhcsa-系列-十一-使用-firewalld-和-iptables-来控制网络流量" aria-label="Permalink to “RHCSA 系列（十一）: 使用 firewalld 和 iptables 来控制网络流量”">​</a></h1><p>简单来说，防火墙就是一个基于一系列预先定义的规则（例如流量包的目的地或来源，流量的类型等）的安全系统，它控制着一个网络中的流入和流出流量。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Control-Network-Traffic-Using-Firewall.png" alt="使用 FirewallD 和 Iptables 来控制网络流量"></p><p><em>RHCSA: 使用 FirewallD 和 Iptables 来控制网络流量 – Part 11</em></p><p>在本文中，我们将回顾 firewalld 和 iptables 的基础知识。前者是 RHEL 7 中的默认动态防火墙守护进程，而后者则是针对 Linux 的传统的防火墙服务，大多数的系统和网络管理员都非常熟悉它，并且在 RHEL 7 中也可以用。</p><h3 id="firewalld-和-iptables-的一个比较" tabindex="-1">FirewallD 和 Iptables 的一个比较 <a class="header-anchor" href="#firewalld-和-iptables-的一个比较" aria-label="Permalink to “FirewallD 和 Iptables 的一个比较”">​</a></h3><p>在后台， firewalld 和 iptables 服务都通过相同的接口来与内核中的 netfilter 框架相交流，这不足为奇，即它们都通过 iptables 命令来与 netfilter 交互。然而，与 iptables 服务相反， firewalld 可以在不丢失现有连接的情况下，在正常的系统操作期间更改设定。</p><p>在默认情况下， firewalld 应该已经安装在你的 RHEL 系统中了，尽管它可能没有在运行。你可以使用下面的命令来确认（firewall-config 是用户界面配置工具）：</p><pre><code># yum info firewalld firewall-config
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-FirewallD-Information.png" alt="检查 FirewallD 的信息"></p><p><em>检查 FirewallD 的信息</em></p><p>以及，</p><pre><code># systemctl status -l firewalld.service
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-FirewallD-Status.png" alt="检查 FirewallD 的状态"></p><p><em>检查 FirewallD 的状态</em></p><p>另一方面， iptables 服务在默认情况下没有被包含在 RHEL 系统中，但可以被安装上。</p><pre><code># yum update &amp;&amp; yum install iptables-services
</code></pre><p>这两个守护进程都可以使用常规的 systemd 命令来在开机时被启动和开启：</p><pre><code># systemctl start firewalld.service | iptables-service.service
# systemctl enable firewalld.service | iptables-service.service
</code></pre>`,19)),t("p",null,[e[1]||(e[1]=l("另外，请阅读：",-1)),r(p,{href:"https://linux.cn/article-5926-1.html"},{default:i(()=>[...e[0]||(e[0]=[l("管理 Systemd 服务的实用命令",-1)])]),_:1})]),e[33]||(e[33]=a(`<p>至于配置文件， iptables 服务使用 <code>/etc/sysconfig/iptables</code> 文件（假如这个软件包在你的系统中没有被安装，则这个文件将不存在）。在一个被用作集群节点的 RHEL 7 机子上，这个文件看起来是这样：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Iptables-Rules.png" alt="Iptables 防火墙配置文件"></p><p><em>Iptables 防火墙配置文件</em></p><p>而 firewalld 则在两个目录中存储它的配置文件，即 <code>/usr/lib/firewalld</code> 和 <code>/etc/firewalld</code>：</p><pre><code># ls /usr/lib/firewalld /etc/firewalld
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Firewalld-configuration.png" alt="FirewallD 的配置文件"></p><p><em>FirewallD 的配置文件</em></p><p>在这篇文章中后面，我们将进一步查看这些配置文件，在那之后，我们将在这两个地方添加一些规则。现在，是时候提醒你了，你总可以使用下面的命令来找到更多有关这两个工具的信息。</p><pre><code># man firewalld.conf
# man firewall-cmd
# man iptables
</code></pre>`,9)),t("p",null,[e[3]||(e[3]=l("除了这些，记得查看一下当前系列的第一篇 ",-1)),r(p,{href:"https://linux.cn/article-6133-1.html"},{default:i(()=>[...e[2]||(e[2]=[l("RHCSA 系列（一）: 回顾基础命令及系统文档",-1)])]),_:1}),e[4]||(e[4]=l("，在其中我描述了几种渠道来得到安装在你的 RHEL 7 系统上的软件包的信息。",-1))]),e[34]||(e[34]=t("h3",{id:"使用-iptables-来控制网络流量",tabindex:"-1"},[l("使用 Iptables 来控制网络流量 "),t("a",{class:"header-anchor",href:"#使用-iptables-来控制网络流量","aria-label":"Permalink to “使用 Iptables 来控制网络流量”"},"​")],-1)),t("p",null,[e[6]||(e[6]=l("在进一步深入之前，或许你需要参考 Linux 基金会认证工程师（Linux Foundation Certified Engineer,LFCE） 系列中的 ",-1)),r(p,{href:"http://www.tecmint.com/configure-iptables-firewall/"},{default:i(()=>[...e[5]||(e[5]=[l("配置 Iptables 防火墙 – Part 8",-1)])]),_:1}),e[7]||(e[7]=l(" 来复习你脑中有关 iptables 的知识。",-1))]),e[35]||(e[35]=a(`<p><strong>例 1：同时允许流入和流出的网络流量</strong></p><p>TCP 端口 80 和 443 是 Apache web 服务器使用的用来处理常规（HTTP）和安全（HTTPS）网络流量的默认端口。你可以像下面这样在 enp0s3 接口上允许流入和流出网络流量通过这两个端口：</p><pre><code># iptables -A INPUT -i enp0s3 -p tcp --dport 80 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A OUTPUT -o enp0s3 -p tcp --sport 80 -m state --state ESTABLISHED -j ACCEPT
# iptables -A INPUT -i enp0s3 -p tcp --dport 443 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A OUTPUT -o enp0s3 -p tcp --sport 443 -m state --state ESTABLISHED -j ACCEPT
</code></pre><p><strong>例 2：从某个特定网络中阻挡所有（或某些）流入连接</strong></p><p>或许有时你需要阻挡来自于某个特定网络的所有（或某些）类型的来源流量，比方说 192.168.1.0/24：</p><pre><code># iptables -I INPUT -s 192.168.1.0/24 -j DROP
</code></pre><p>上面的命令将丢掉所有来自 192.168.1.0/24 网络的网络包，而</p><pre><code># iptables -A INPUT -s 192.168.1.0/24 --dport 22 -j ACCEPT
</code></pre><p>将只允许通过端口 22 的流入流量。</p><p><strong>例 3：将流入流量重定向到另一个目的地</strong></p><p>假如你不仅使用你的 RHEL 7 机子来作为一个软件防火墙，而且还将它作为一个硬件防火墙，使得它位于两个不同的网络之间，那么在你的系统上 IP 转发一定已经被开启了。假如没有开启，你需要编辑 <code>/etc/sysctl.conf</code> 文件并将 <code>net.ipv4.ip_forward</code> 的值设为 1，即：</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p>接着保存更改，关闭你的文本编辑器，并最终运行下面的命令来应用更改：</p><pre><code># sysctl -p /etc/sysctl.conf
</code></pre><p>例如，你可能在一个内部的机子上安装了一个打印机，它的 IP 地址为 192.168.0.10，CUPS 服务在端口 631 上进行监听（同时在你的打印服务器和你的防火墙上）。为了从防火墙另一边的客户端传递打印请求，你应该添加下面的 iptables 规则：</p><pre><code># iptables -t nat -A PREROUTING -i enp0s3 -p tcp --dport 631 -j DNAT --to 192.168.0.10:631
</code></pre><p>请记住 iptables 会逐条地读取它的规则，所以请确保默认的策略或后面的规则不会重载上面例子中那些规则。</p><h3 id="firewalld-入门" tabindex="-1">FirewallD 入门 <a class="header-anchor" href="#firewalld-入门" aria-label="Permalink to “FirewallD 入门”">​</a></h3>`,18)),t("p",null,[e[9]||(e[9]=l("firewalld 引入的一个变化是区域（zone） （注：翻译参考了 ",-1)),r(p,{href:"https://fedoraproject.org/wiki/FirewallD/zh-cn"},{default:i(()=>[...e[8]||(e[8]=[l("https://fedoraproject.org/wiki/FirewallD/zh-cn",-1)])]),_:1}),e[10]||(e[10]=l(" ）。这个概念允许将网路划分为拥有不同信任级别的区域，由用户决定将设备和流量放置到哪个区域。",-1))]),e[36]||(e[36]=t("p",null,"要获取活动的区域，使用：",-1)),e[37]||(e[37]=t("pre",null,[t("code",null,`# firewall-cmd --get-active-zones
`)],-1)),e[38]||(e[38]=t("p",null,"在下面的例子中，public 区域是激活的，并且 enp0s3 接口被自动地分配到了这个区域。要查看有关一个特定区域的所有信息，可使用：",-1)),e[39]||(e[39]=t("pre",null,[t("code",null,`# firewall-cmd --zone=public --list-all
`)],-1)),e[40]||(e[40]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/05/View-FirewallD-Zones.png",alt:"列出所有的 Firewalld 区域"})],-1)),e[41]||(e[41]=t("p",null,[t("em",null,"列出所有的 Firewalld 区域")],-1)),t("p",null,[e[12]||(e[12]=l("由于你可以在 ",-1)),r(p,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/Security_Guide/sec-Using_Firewalls.html"},{default:i(()=>[...e[11]||(e[11]=[l("RHEL 7 安全指南",-1)])]),_:1}),e[13]||(e[13]=l(" 中阅读到更多有关区域的知识，这里我们将仅列出一些特别的例子。",-1))]),e[42]||(e[42]=a(`<p><strong>例 4：允许服务通过防火墙</strong></p><p>要获取受支持的服务的列表，可以使用：</p><pre><code># firewall-cmd --get-services
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/List-All-Supported-Services.png" alt="列出所有受支持的服务"></p><p><em>列出所有受支持的服务</em></p><p>要立刻生效且在随后重启后都可以让 http 和 https 网络流量通过防火墙，可以这样：</p><pre><code># firewall-cmd --zone=MyZone --add-service=http
# firewall-cmd --zone=MyZone --permanent --add-service=http
# firewall-cmd --zone=MyZone --add-service=https
# firewall-cmd --zone=MyZone --permanent --add-service=https
# firewall-cmd --reload
</code></pre><p>假如 <code>-–zone</code> 被忽略，则使用默认的区域（你可以使用 <code>firewall-cmd –get-default-zone</code>来查看）。</p><p>若要移除这些规则，可以在上面的命令中将 <code>add</code> 替换为 <code>remove</code>。</p><p><strong>例 5：IP 转发或端口转发</strong></p><p>首先，你需要查看在目标区域中，伪装（masquerading）是否被开启：</p><pre><code># firewall-cmd --zone=MyZone --query-masquerade
</code></pre><p>在下面的图片中，我们可以看到对于外部区域，伪装已被开启，但对于公用区域则没有：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Check-masquerading.png" alt="在 firewalld 中查看伪装状态"></p><p><em>查看伪装状态</em></p><p>你可以为公共区域开启伪装：</p><pre><code># firewall-cmd --zone=public --add-masquerade
</code></pre><p>或者在外部区域中使用伪装。下面是使用 firewalld 来重复例 3 中的任务所需的命令：</p><pre><code># firewall-cmd --zone=external --add-forward-port=port=631:proto=tcp:toport=631:toaddr=192.168.0.10
</code></pre><p>不要忘了重新加载防火墙。</p>`,20)),t("p",null,[e[15]||(e[15]=l("在 RHCSA 系列的 ",-1)),r(p,{href:"https://linux.cn/article-6286-1.html"},{default:i(()=>[...e[14]||(e[14]=[l("第九部分",-1)])]),_:1}),e[16]||(e[16]=l(" 你可以找到更深入的例子，在那篇文章中我们解释了如何允许或禁用通常被 web 服务器和 ftp 服务器使用的端口，以及在针对这两个服务所使用的默认端口被改变时，如何更改相应的规则。另外，你或许想参考 firewalld 的 wiki 来查看更深入的例子。",-1))]),t("ul",null,[t("li",null,[e[18]||(e[18]=l("延伸阅读： ",-1)),r(p,{href:"http://www.tecmint.com/firewalld-rules-for-centos-7/"},{default:i(()=>[...e[17]||(e[17]=[l("在 RHEL 7 中配置防火墙的几个实用的 firewalld 例子",-1)])]),_:1})])]),e[43]||(e[43]=t("h3",{id:"总结",tabindex:"-1"},[l("总结 "),t("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),e[44]||(e[44]=t("p",null,"在这篇文章中，我们已经解释了防火墙是什么，介绍了在 RHEL 7 中用来实现防火墙的几个可用的服务，并提供了可以帮助你入门防火墙的几个例子。假如你有任何的评论，建议或问题，请随意使用下面的评论框来让我们知晓。这里就事先感谢了！",-1)),e[45]||(e[45]=t("hr",null,null,-1)),t("p",null,[e[20]||(e[20]=l("via: ",-1)),r(p,{href:"http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/"},{default:i(()=>[...e[19]||(e[19]=[l("http://www.tecmint.com/firewalld-vs-iptables-and-control-network-traffic-in-firewall/",-1)])]),_:1})]),t("p",null,[e[24]||(e[24]=l("作者：",-1)),r(p,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>[...e[21]||(e[21]=[l("Gabriel Cánepa",-1)])]),_:1}),e[25]||(e[25]=l(" 译者：",-1)),r(p,{href:"https://github.com/FSSlc"},{default:i(()=>[...e[22]||(e[22]=[l("FSSlc",-1)])]),_:1}),e[26]||(e[26]=l(" 校对：",-1)),r(p,{href:"https://github.com/wxy"},{default:i(()=>[...e[23]||(e[23]=[l("wxy",-1)])]),_:1})]),t("p",null,[e[29]||(e[29]=l("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[27]||(e[27]=[l("LCTT",-1)])]),_:1}),e[30]||(e[30]=l(" 原创翻译，",-1)),r(p,{href:"https://linux.cn/"},{default:i(()=>[...e[28]||(e[28]=[l("Linux中国",-1)])]),_:1}),e[31]||(e[31]=l(" 荣誉推出",-1))])])}const c=n(w,[["render",f]]);export{A as __pageData,c as default};
